-- 6. MAXIMUS — [automate_dv.ma_sat] SAT_AUG_POLICY_PREMIUM_HEAD   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. augmented satellite,
-- automate_dv.ma_sat; PK POLICY_HKEY, child key ADJUSTED_INDICATOR, COVERAGE_REFERENCE,
-- PREMIUM_HEAD_CODE, SECTION; 2 RECORD_SOURCE group(s):
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS [1
-- col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [1 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member.
----------------------------------------------------------------------------------------
-- STEP 1 (static, run anytime) -- HASHDIFF integrity. PASS here = the change-detection fingerprint is sound. SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_AUG_POLICY_PREMIUM_HEAD' as satellite, '2 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ADJUSTED_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(COVERAGE_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(GROSS_HEAD_PREMIUM AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PREMIUM_HEAD_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SECTION AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ADJUSTED_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(COVERAGE_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(GROSS_HEAD_PREMIUM AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PREMIUM_HEAD_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SECTION AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(POLICY_HKEY, 'HEX'), null)) within group (order by POLICY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY_PREMIUM_HEAD
 where (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW');

-- STEP 2 (BEFORE) -- set $DM_H_RUN (with your <M#>) and $DM_H_PHASE='BEFORE', then run this CDC capture. Re-run it again in STEP 6 after setting phase to AFTER.
insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY_PREMIUM_HEAD where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_AUG_POLICY_PREMIUM_HEAD' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_pol_ins_cov
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(wk0."POLICY_NUMBER"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."POLICY_NUMBER"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               to_varchar('N') as cdk_1,
               to_varchar(nullif(trim(wk1."POL_RISK_ID"), '') || '#' || nullif(trim((nullif(trim(to_varchar(b."COVER_CODE")), ''))), '')) as cdk_2,
               to_varchar('COVER_TOTAL_PREMIUM') as cdk_3,
               to_varchar('COVER') as cdk_4,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar(b."TOTAL_PREMIUM")), ''))) as GROSS_HEAD_PREMIUM
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS b
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk0
                    on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS wk1
                    on wk1."KEY_HASH" = b."PARENT_KEY_HASH"
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1, cdk_2, cdk_3, cdk_4 order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select POLICY_HKEY as hkey, coalesce(to_varchar(ADJUSTED_INDICATOR), '^^') || '|' || coalesce(to_varchar(COVERAGE_REFERENCE), '^^') || '|' || coalesce(to_varchar(PREMIUM_HEAD_CODE), '^^') || '|' || coalesce(to_varchar(SECTION), '^^') as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY_PREMIUM_HEAD
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS' and POLICY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, coalesce(e.cdk_1, '^^') || '|' || coalesce(e.cdk_2, '^^') || '|' || coalesce(e.cdk_3, '^^') || '|' || coalesce(e.cdk_4, '^^') as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.GROSS_HEAD_PREMIUM AS VARCHAR))), ''), '^^'))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_POLICY_PREMIUM_HEAD', 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s2 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY_PREMIUM_HEAD where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_AUG_POLICY_PREMIUM_HEAD' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_pol_ins_rskp_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(wk0."POLICY_NUMBER"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."POLICY_NUMBER"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               to_varchar('N') as cdk_1,
               to_varchar(coalesce(nullif(trim(wk3."POL_RISK_ID"), '') || '#ALL','')) as cdk_2,
               to_varchar('GROSS_PREMIUM') as cdk_3,
               to_varchar('RISK') as cdk_4,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar(b."GROSS_PREMIUM")), ''))) as GROSS_HEAD_PREMIUM
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW b
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk0
                    on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY wk1
                    on wk1."KEY_HASH" = b."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY wk2
                    on wk2."KEY_HASH" = wk1."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS wk3
                    on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk4
                    on wk4."KEY_HASH" = wk3."PARENT_KEY_HASH"
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey, cdk_1, cdk_2, cdk_3, cdk_4 order by ldts desc) = 1
),
n2 as (  -- satellite history per sampled key
    select POLICY_HKEY as hkey, coalesce(to_varchar(ADJUSTED_INDICATOR), '^^') || '|' || coalesce(to_varchar(COVERAGE_REFERENCE), '^^') || '|' || coalesce(to_varchar(PREMIUM_HEAD_CODE), '^^') || '|' || coalesce(to_varchar(SECTION), '^^') as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY_PREMIUM_HEAD
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and POLICY_HKEY in (select hkey from s2)
     group by 1, 2
),
x2 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, coalesce(e.cdk_1, '^^') || '|' || coalesce(e.cdk_2, '^^') || '|' || coalesce(e.cdk_3, '^^') || '|' || coalesce(e.cdk_4, '^^') as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.GROSS_HEAD_PREMIUM AS VARCHAR))), ''), '^^'))) as raw_hash
      from e2 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_POLICY_PREMIUM_HEAD', 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n2 n full outer join x2 x on x.hkey = n.hkey and x.cdk = n.cdk;

-- STEP 3 (pick a key) -- map a sampled BEFORE hkey to its RAW business key. Copy one business_key value to use in STEP 4.
with s_bk as (  -- sampled BEFORE hkeys for this satellite
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_AUG_POLICY_PREMIUM_HEAD'
)
-- via resolved_mt__uwr_pol_ins_cov (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS)  [RAW key columns: FOREIGN_KEY; parent columns: w0_policy_number]
select 'SAT_AUG_POLICY_PREMIUM_HEAD' as satellite, 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(wk0."POLICY_NUMBER"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."POLICY_NUMBER"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar(b."FOREIGN_KEY"), '^^') || '|' || coalesce(to_varchar(wk0."POLICY_NUMBER"), '^^') as business_key, (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as inc_job_updated_at,
       'BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS' as raw_table
  from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS b
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk0
            on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS wk1
            on wk1."KEY_HASH" = b."PARENT_KEY_HASH"
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(wk0."POLICY_NUMBER"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."POLICY_NUMBER"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via resolved_mt__uwr_pol_ins_rskp_sp_pv (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW)  [RAW key columns: FOREIGN_KEY; parent columns: w0_policy_number]
select 'SAT_AUG_POLICY_PREMIUM_HEAD' as satellite, 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(wk0."POLICY_NUMBER"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."POLICY_NUMBER"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar(b."FOREIGN_KEY"), '^^') || '|' || coalesce(to_varchar(wk0."POLICY_NUMBER"), '^^') as business_key, (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as inc_job_updated_at,
       'BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as raw_table
  from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW b
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk0
            on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY wk1
            on wk1."KEY_HASH" = b."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY wk2
            on wk2."KEY_HASH" = wk1."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS wk3
            on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk4
            on wk4."KEY_HASH" = wk3."PARENT_KEY_HASH"
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(wk0."POLICY_NUMBER"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."POLICY_NUMBER"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS
   set "TOTAL_PREMIUM" = coalesce(to_varchar("TOTAL_PREMIUM"), '') || '_T',
       "REC_REFRESH_AT" = current_timestamp()
 where "FOREIGN_KEY" = '<FOREIGN_KEY>';

-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
   set "GROSS_PREMIUM" = coalesce(to_varchar("GROSS_PREMIUM"), '') || '_T',
       "REC_REFRESH_AT" = current_timestamp()
 where "FOREIGN_KEY" = '<FOREIGN_KEY>';

-- STEP 7 (result for THIS sat) -- after AFTER capture, run this. PASS = every changed key got >= 1 new row; NOT TESTED = no change reached the sample.
with b as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_AUG_POLICY_PREMIUM_HEAD'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_AUG_POLICY_PREMIUM_HEAD'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'MAXIMUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



----------------------------------------------------------------------------------------
-- 7. MAXIMUS — [automate_dv.sat] SAT_CLAIM_HEADER   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- automate_dv.sat; PK CLAIM_HKEY; 5 RECORD_SOURCE group(s):
-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS [6 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [1 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW
-- [11 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [1 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW
-- [1 col(s)].
----------------------------------------------------------------------------------------
-- STEP 1 (static, run anytime) -- HASHDIFF integrity. PASS here = the change-detection fingerprint is sound. SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_CLAIM_HEADER' as satellite, '5 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(CATASTROPHE_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_CATEGORY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_HANDLER_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_REFERENCE_NUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_SUB_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_TYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(HANDLING_ORG_UNIT_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INTIMATED_BY_ROLE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INTIMATION_CHANNEL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LOSS_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NOTIFICATION_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PRIORITY_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(REGISTRATION_DATE AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(CATASTROPHE_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_CATEGORY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_HANDLER_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_REFERENCE_NUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_SUB_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CLAIM_TYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(HANDLING_ORG_UNIT_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INTIMATED_BY_ROLE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(INTIMATION_CHANNEL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LOSS_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NOTIFICATION_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PRIORITY_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(REGISTRATION_DATE AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(CLAIM_HKEY, 'HEX'), null)) within group (order by CLAIM_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER
 where (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW');

-- STEP 2 (BEFORE) -- set $DM_H_RUN (with your <M#>) and $DM_H_PHASE='BEFORE', then run this CDC capture. Re-run it again in STEP 6 after setting phase to AFTER.
insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct CLAIM_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_CLAIM_HEADER' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_mt__clm_clmd
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))),'') is not null then nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar("CLAIM_BUCKET")), ''))) as CLAIM_CATEGORY,
               to_varchar((nullif(trim(to_varchar("SUBCLAIMNO")), ''))) as CLAIM_REFERENCE_NUMBER,
               to_varchar((nullif(trim(to_varchar("CLAIMSTATUS")), ''))) as CLAIM_STATUS,
               to_varchar((nullif(trim(to_varchar("CLAIMBRANCH")), ''))) as HANDLING_ORG_UNIT_CODE,
               to_varchar((nullif(trim(to_varchar("LOSSDATE")), ''))) as LOSS_DATE,
               to_varchar((nullif(trim(to_varchar("INTIMATIONDATE")), ''))) as NOTIFICATION_DATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select CLAIM_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS' and CLAIM_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.CLAIM_CATEGORY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CLAIM_REFERENCE_NUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CLAIM_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.HANDLING_ORG_UNIT_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.LOSS_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.NOTIFICATION_DATE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_CLAIM_HEADER', 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s2 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct CLAIM_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_CLAIM_HEADER' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__clm_clmd_clma_msp_msd_prop_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar(b."INTIMATION_DATE")), ''))) as NOTIFICATION_DATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW b
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk0
                    on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n2 as (  -- satellite history per sampled key
    select CLAIM_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' and CLAIM_HKEY in (select hkey from s2)
     group by 1, 2
),
x2 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.NOTIFICATION_DATE AS VARCHAR))), ''), '^^'))) as raw_hash
      from e2 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_CLAIM_HEADER', 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n2 n full outer join x2 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s3 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct CLAIM_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_CLAIM_HEADER' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW'
),
e3 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__clm_clmd_clmap_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar(b."CLAIMNO")), ''))),''), nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim((nullif(trim(to_varchar(b."CLAIMNO")), ''))), ''), nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar(b."CATASTROPHIC_EVENT_CODE")), ''))) as CATASTROPHE_CODE,
               to_varchar((nullif(trim(to_varchar(b."CLAIM_TYPES")), ''))) as CLAIM_CATEGORY,
               to_varchar((nullif(trim(to_varchar(b."CLAIM_OWNER")), ''))) as CLAIM_HANDLER_REFERENCE,
               to_varchar((nullif(trim(to_varchar(b."CLAIM_SUBSTATUS")), ''))) as CLAIM_SUB_STATUS,
               to_varchar((nullif(trim(to_varchar(b."TYPE_OF_CLAIM")), ''))) as CLAIM_TYPE,
               to_varchar((nullif(trim(to_varchar(b."CLAIM_HANDLING_LOCATION_CODEMACT_LOCATION_CODE")), ''))) as HANDLING_ORG_UNIT_CODE,
               to_varchar((nullif(trim(to_varchar(b."CLAIM_REPORTED_BY")), ''))) as INTIMATED_BY_ROLE,
               to_varchar((nullif(trim(to_varchar(b."CLAIM_INTIMATION_TYPE")), ''))) as INTIMATION_CHANNEL,
               to_varchar((nullif(trim(to_varchar(b."DATE_OF_ACCIDENT")), ''))) as LOSS_DATE,
               to_varchar((nullif(trim(to_varchar(b."PRIORITY")), ''))) as PRIORITY_CODE,
               to_varchar((nullif(trim(to_varchar(b."CLAIM_REGISTRATION_DATE")), ''))) as REGISTRATION_DATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW b
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk0
                    on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES wk1
                    on wk1."KEY_HASH" = b."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE wk2
                    on wk2."KEY_HASH" = wk1."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk3
                    on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
      )
     where hkey in (select hkey from s3) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n3 as (  -- satellite history per sampled key
    select CLAIM_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW' and CLAIM_HKEY in (select hkey from s3)
     group by 1, 2
),
x3 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.CATASTROPHE_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CLAIM_CATEGORY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CLAIM_HANDLER_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CLAIM_SUB_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CLAIM_TYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.HANDLING_ORG_UNIT_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.INTIMATED_BY_ROLE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.INTIMATION_CHANNEL AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.LOSS_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PRIORITY_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.REGISTRATION_DATE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e3 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_CLAIM_HEADER', 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n3 n full outer join x3 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s4 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct CLAIM_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
