     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_CLAIM_HEADER' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
),
e4 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__clm_clmd_clmcov_msd_prop_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar(b."INTIMATION_DATE")), ''))) as NOTIFICATION_DATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW b
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk0
                    on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
      )
     where hkey in (select hkey from s4) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n4 as (  -- satellite history per sampled key
    select CLAIM_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' and CLAIM_HKEY in (select hkey from s4)
     group by 1, 2
),
x4 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.NOTIFICATION_DATE AS VARCHAR))), ''), '^^'))) as raw_hash
      from e4 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_CLAIM_HEADER', 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n4 n full outer join x4 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s5 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct CLAIM_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_CLAIM_HEADER' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW'
),
e5 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__clm_clmd_clmrsk_rska_properties_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar(b."EVENT_DATE")), ''))) as LOSS_DATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW b
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk0
                    on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
      )
     where hkey in (select hkey from s5) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n5 as (  -- satellite history per sampled key
    select CLAIM_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_CLAIM_HEADER
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW' and CLAIM_HKEY in (select hkey from s5)
     group by 1, 2
),
x5 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.LOSS_DATE AS VARCHAR))), ''), '^^'))) as raw_hash
      from e5 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_CLAIM_HEADER', 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n5 n full outer join x5 x on x.hkey = n.hkey and x.cdk = n.cdk;

-- STEP 3 (pick a key) -- map a sampled BEFORE hkey to its RAW business key. Copy one business_key value to use in STEP 4.
with s_bk as (  -- sampled BEFORE hkeys for this satellite
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_CLAIM_HEADER'
)
-- via stg_mt__clm_clmd (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS)
select 'SAT_CLAIM_HEADER' as satellite, 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))),'') is not null then nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))), '') end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar("CLAIMNO"), '^^') as business_key, (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as inc_job_updated_at,
       'BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS' as raw_table
  from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))),'') is not null then nullif(trim((nullif(trim(to_varchar("CLAIMNO")), ''))), '') end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via resolved_mt__clm_clmd_clma_msp_msd_prop_pv (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW)  [RAW key columns: FOREIGN_KEY; parent columns: w0_claimno]
select 'SAT_CLAIM_HEADER' as satellite, 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar(b."FOREIGN_KEY"), '^^') || '|' || coalesce(to_varchar(wk0."CLAIMNO"), '^^') as business_key, (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as inc_job_updated_at,
       'BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' as raw_table
  from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW b
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk0
            on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via resolved_mt__clm_clmd_clmap_pv (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW)  [RAW key columns: CLAIMNO, FOREIGN_KEY; parent columns: w0_claimno]
select 'SAT_CLAIM_HEADER' as satellite, 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar(b."CLAIMNO")), ''))),''), nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim((nullif(trim(to_varchar(b."CLAIMNO")), ''))), ''), nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar(b."CLAIMNO"), '^^') || '|' || coalesce(to_varchar(b."FOREIGN_KEY"), '^^') || '|' || coalesce(to_varchar(wk0."CLAIMNO"), '^^') as business_key, (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as inc_job_updated_at,
       'BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW' as raw_table
  from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW b
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk0
            on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES wk1
            on wk1."KEY_HASH" = b."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE wk2
            on wk2."KEY_HASH" = wk1."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk3
            on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim((nullif(trim(to_varchar(b."CLAIMNO")), ''))),''), nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim((nullif(trim(to_varchar(b."CLAIMNO")), ''))), ''), nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via resolved_mt__clm_clmd_clmcov_msd_prop_pv (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW)  [RAW key columns: FOREIGN_KEY; parent columns: w0_claimno]
select 'SAT_CLAIM_HEADER' as satellite, 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar(b."FOREIGN_KEY"), '^^') || '|' || coalesce(to_varchar(wk0."CLAIMNO"), '^^') as business_key, (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as inc_job_updated_at,
       'BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' as raw_table
  from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW b
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk0
            on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via resolved_mt__clm_clmd_clmrsk_rska_properties_pv (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW)  [RAW key columns: FOREIGN_KEY; parent columns: w0_claimno]
select 'SAT_CLAIM_HEADER' as satellite, 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar(b."FOREIGN_KEY"), '^^') || '|' || coalesce(to_varchar(wk0."CLAIMNO"), '^^') as business_key, (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as inc_job_updated_at,
       'BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW' as raw_table
  from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW b
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk0
            on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_CLAIM|' || (nullif(trim(case when coalesce(nullif(trim(wk0."CLAIMNO"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."CLAIMNO"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS
   set "CLAIM_BUCKET" = coalesce(to_varchar("CLAIM_BUCKET"), '') || '_T',
       "REC_REFRESH_AT" = current_timestamp()
 where "CLAIMNO" = '<CLAIMNO>';

-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
   set "INTIMATION_DATE" = coalesce(to_varchar("INTIMATION_DATE"), '') || '_T',
       "REC_REFRESH_AT" = current_timestamp()
 where "FOREIGN_KEY" = '<FOREIGN_KEY>';

-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW
   set "CATASTROPHIC_EVENT_CODE" = coalesce(to_varchar("CATASTROPHIC_EVENT_CODE"), '') || '_T',
       "REC_REFRESH_AT" = current_timestamp()
 where "CLAIMNO" = '<CLAIMNO>' and "FOREIGN_KEY" = '<FOREIGN_KEY>';

-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_COVER_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
   set "INTIMATION_DATE" = coalesce(to_varchar("INTIMATION_DATE"), '') || '_T',
       "REC_REFRESH_AT" = current_timestamp()
 where "FOREIGN_KEY" = '<FOREIGN_KEY>';

-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_PROPERTIES_PIVOT_VW
   set "EVENT_DATE" = coalesce(to_varchar("EVENT_DATE"), '') || '_T',
       "REC_REFRESH_AT" = current_timestamp()
 where "FOREIGN_KEY" = '<FOREIGN_KEY>';

-- STEP 7 (result for THIS sat) -- after AFTER capture, run this. PASS = every changed key got >= 1 new row; NOT TESTED = no change reached the sample.
with b as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_CLAIM_HEADER'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_CLAIM_HEADER'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'MAXIMUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



----------------------------------------------------------------------------------------
-- 8. MAXIMUS — [automate_dv.sat] SAT_COVERAGE_CONDITIONS   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- automate_dv.sat; PK COVERAGE_HKEY; 4 RECORD_SOURCE group(s):
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS_COVER_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [1 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [1 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY_RULE_LIST_PIVOT_VW
-- [1 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW
-- [1 col(s)].
----------------------------------------------------------------------------------------
-- STEP 1 (static, run anytime) -- HASHDIFF integrity. PASS here = the change-detection fingerprint is sound. SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_COVERAGE_CONDITIONS' as satellite, '4 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(CONDITION_DESCRIPTION AS VARCHAR))), ''), '^^')) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(IFNULL(NULLIF(UPPER(TRIM(CAST(CONDITION_DESCRIPTION AS VARCHAR))), ''), '^^')) AS BINARY(16)), to_varchar(COVERAGE_HKEY, 'HEX'), null)) within group (order by COVERAGE_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COVERAGE_CONDITIONS
 where (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS_COVER_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY_RULE_LIST_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW');

-- STEP 2 (BEFORE) -- set $DM_H_RUN (with your <M#>) and $DM_H_PHASE='BEFORE', then run this CDC capture. Re-run it again in STEP 6 after setting phase to AFTER.
insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct COVERAGE_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COVERAGE_CONDITIONS where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS_COVER_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_COVERAGE_CONDITIONS' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS_COVER_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_pol_ins_cov_covp_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_COVERAGE|' || (nullif(trim(case when nullif(trim(wk3."COVER_CODE"),'') is not null then 'COV:' || nullif(trim(wk3."COVER_CODE"), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
