                    on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS wk4
                    on wk4."KEY_HASH" = wk3."PARENT_KEY_HASH"
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select COVERAGE_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COVERAGE_CONDITIONS
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_COVER_DETAILS_COVER_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and COVERAGE_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.CONDITION_DESCRIPTION AS VARCHAR))), ''), '^^'))) as raw_hash
      from e1 e group by 1, 2
