        -- via resolved_mt__uwr_qpd_rskl_rskp_rl_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_COVERAGE|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar(b."COVER_CODE")), ''))),'') is not null then 'COV:' || nullif(trim((nullif(trim(to_varchar(b."COVER_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) as hkey,
