       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk4
            on wk4."KEY_HASH" = wk3."PARENT_KEY_HASH"
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_COVERAGE|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar(b."COVER_CODE")), ''))),'') is not null then 'COV:' || nullif(trim((nullif(trim(to_varchar(b."COVER_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via resolved_mt__uwr_qpd_rskl_rskc_rskc_prop_rl_pv (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY_RULE_LIST_PIVOT_VW)  [RAW key columns: none; parent columns: w2_cover_code]
select 'SAT_COVERAGE_CONDITIONS' as satellite, 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY_RULE_LIST_PIVOT_VW' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_COVERAGE|' || (nullif(trim(case when nullif(trim(wk2."COVER_CODE"),'') is not null then 'COV:' || nullif(trim(wk2."COVER_CODE"), '') end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar(wk2."COVER_CODE"), '^^') as business_key, (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as inc_job_updated_at,
       'BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY_RULE_LIST_PIVOT_VW' as raw_table
  from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY_RULE_LIST_PIVOT_VW b
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY_RULE_LIST wk0
            on wk0."KEY_HASH" = b."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER_RISK_COVER_PROPERTY wk1
            on wk1."KEY_HASH" = wk0."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_COVER wk2
            on wk2."KEY_HASH" = wk1."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST wk3
            on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS wk4
            on wk4."KEY_HASH" = wk3."PARENT_KEY_HASH"
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_COVERAGE|' || (nullif(trim(case when nullif(trim(wk2."COVER_CODE"),'') is not null then 'COV:' || nullif(trim(wk2."COVER_CODE"), '') end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
union all
-- via resolved_mt__uwr_qpd_rskl_rskp_rl_pv (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW)  [RAW key columns: COVER_CODE; parent columns: none]
select 'SAT_COVERAGE_CONDITIONS' as satellite, 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_COVERAGE|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar(b."COVER_CODE")), ''))),'') is not null then 'COV:' || nullif(trim((nullif(trim(to_varchar(b."COVER_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar(b."COVER_CODE"), '^^') as business_key, (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as inc_job_updated_at,
       'BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW' as raw_table
  from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW b
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST wk0
            on wk0."KEY_HASH" = b."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY wk1
            on wk1."KEY_HASH" = wk0."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST wk2
            on wk2."KEY_HASH" = wk1."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS wk3
            on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_COVERAGE|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar(b."COVER_CODE")), ''))),'') is not null then 'COV:' || nullif(trim((nullif(trim(to_varchar(b."COVER_CODE")), ''))), '') end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
   set "SUB_CONDITION1" = coalesce(to_varchar("SUB_CONDITION1"), '') || '_T',
       "REC_REFRESH_AT" = current_timestamp()
 where "COVER_CODE" = '<COVER_CODE>';

-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_RISK_LIST_RISK_PROPERTY_RULE_LIST_PIVOT_VW
   set "SUB_CONDITION1" = coalesce(to_varchar("SUB_CONDITION1"), '') || '_T',
       "REC_REFRESH_AT" = current_timestamp()
 where "COVER_CODE" = '<COVER_CODE>';

-- STEP 7 (result for THIS sat) -- after AFTER capture, run this. PASS = every changed key got >= 1 new row; NOT TESTED = no change reached the sample.
with b as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_COVERAGE_CONDITIONS'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_COVERAGE_CONDITIONS'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'MAXIMUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



----------------------------------------------------------------------------------------
-- 9. MAXIMUS — [automate_dv.sat] SAT_POLICY_HEADER   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- automate_dv.sat; PK POLICY_HKEY; 7 RECORD_SOURCE group(s):
-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW
-- [3 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW
-- [2 col(s)], MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS [5 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [8 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
-- [14 col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PREVIOUS_POLICY_DETAILS [4
-- col(s)],
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_RULE_LIST_PIVOT_VW
-- [2 col(s)].
----------------------------------------------------------------------------------------
-- STEP 1 (static, run anytime) -- HASHDIFF integrity. PASS here = the change-detection fingerprint is sound. SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'MAXIMUS' as project, 'SAT_POLICY_HEADER' as satellite, '7 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(CO_INSURANCE_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CURRENCY_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FIRST_YEAR_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICYHOLDER_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_CHANNEL_TYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_REFERENCE_NUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_REMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_SUB_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_TERM AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_TYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PREMIUM_FREQUENCY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PREMIUM_PAYER_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PRODUCT_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISK_END_TIME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISK_EXPIRY_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISK_INCEPTION_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISK_START_TIME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SUM_INSURED_TOTAL AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(CO_INSURANCE_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CURRENCY_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FIRST_YEAR_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICYHOLDER_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_CHANNEL_TYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_REFERENCE_NUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_REMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_SUB_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_TERM AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POLICY_TYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PREMIUM_FREQUENCY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PREMIUM_PAYER_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PRODUCT_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISK_END_TIME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISK_EXPIRY_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISK_INCEPTION_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(RISK_START_TIME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SUM_INSURED_TOTAL AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(POLICY_HKEY, 'HEX'), null)) within group (order by POLICY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER
 where (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_PREVIOUS_POLICY_DETAILS') or (RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_QUOTE_PARAM_DETAILS_POLICY_PROPERTY_RULE_LIST_PIVOT_VW');

-- STEP 2 (BEFORE) -- set $DM_H_RUN (with your <M#>) and $DM_H_PHASE='BEFORE', then run this CDC capture. Re-run it again in STEP 6 after setting phase to AFTER.
insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_POLICY_HEADER' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW'
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__clm_clmd_clmap_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when nullif(trim(wk0."POLICYNO"),'') is not null then nullif(trim(wk0."POLICYNO"), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar(b."POLICY_STATUS")), ''))) as POLICY_STATUS,
               to_varchar((nullif(trim(to_varchar(b."POLICY_EXPIRY_DATE")), ''))) as RISK_EXPIRY_DATE,
               to_varchar((nullif(trim(to_varchar(b."POLICY_INCEPTION_DATE")), ''))) as RISK_INCEPTION_DATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW b
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk0
                    on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES wk1
                    on wk1."KEY_HASH" = b."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE wk2
                    on wk2."KEY_HASH" = wk1."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk3
                    on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select POLICY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW' and POLICY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_EXPIRY_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_INCEPTION_DATE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_POLICY_HEADER', 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_ATTRIBUTE_PROPERTIES_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s2 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_POLICY_HEADER' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW'
),
e2 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__clm_clmd_clmrsk_rska_msp_msd_prop_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when nullif(trim(wk0."POLICYNO"),'') is not null then nullif(trim(wk0."POLICYNO"), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar(b."TOTAL_SI_POLICY_CURRENCY")), ''))) as CURRENCY_CODE,
               to_varchar((nullif(trim(to_varchar(b."TOTAL_SI_AMOUNT_IN_POLICY_SI_CURRENCY")), ''))) as SUM_INSURED_TOTAL
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW b
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS wk0
                    on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
      )
     where hkey in (select hkey from s2) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n2 as (  -- satellite history per sampled key
    select POLICY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW' and POLICY_HKEY in (select hkey from s2)
     group by 1, 2
),
x2 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.CURRENCY_CODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.SUM_INSURED_TOTAL AS VARCHAR))), ''), '^^')))) as raw_hash
      from e2 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_POLICY_HEADER', 'MAXIMUS_TRAVEL_NONHLTH_TRV_CLM_VW_DATA_CLAIM_DETAILS_CLAIM_RISK_RISK_ATTRIBUTE_MULTI_SET_PROPERTY_MULTI_SET_DETAIL_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n2 n full outer join x2 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s3 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_POLICY_HEADER' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS'
),
e3 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_mt__uwr_pol
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when nullif(trim((nullif(trim(to_varchar("POLICY_NUMBER")), ''))),'') is not null then nullif(trim((nullif(trim(to_varchar("POLICY_NUMBER")), ''))), '') end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar("REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar("POLICY_STATUS")), ''))) as POLICY_STATUS,
               to_varchar((nullif(trim(to_varchar("POLICY_DURATION")), ''))) as POLICY_TERM,
               to_varchar((nullif(trim(to_varchar("PAYMENT_FREQUENCY")), ''))) as PREMIUM_FREQUENCY,
               to_varchar((nullif(trim(to_varchar("POLICY_EXPIRY_DATE")), ''))) as RISK_EXPIRY_DATE,
               to_varchar((nullif(trim(to_varchar("POLICY_INCEPTION_DATE")), ''))) as RISK_INCEPTION_DATE
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS
      )
     where hkey in (select hkey from s3) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n3 as (  -- satellite history per sampled key
    select POLICY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS' and POLICY_HKEY in (select hkey from s3)
     group by 1, 2
),
x3 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_TERM AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PREMIUM_FREQUENCY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_EXPIRY_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_INCEPTION_DATE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e3 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_POLICY_HEADER', 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n3 n full outer join x3 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s4 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_POLICY_HEADER' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e4 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_pol_ins_rskp_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(wk0."POLICY_NUMBER"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."POLICY_NUMBER"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar(b."SOURCE_OF_BUSINESS")), ''))) as POLICY_CHANNEL_TYPE,
               to_varchar((nullif(trim(to_varchar(b."POLICY_REFERENCE_NUMBER")), ''))) as POLICY_REFERENCE_NUMBER,
               to_varchar((nullif(trim(to_varchar(b."POLICY_DURATION")), ''))) as POLICY_TERM,
               to_varchar(coalesce((nullif(trim(to_varchar(b."POLICY_TYPE")), '')), (nullif(trim(to_varchar(b."TYPEOFPOLICY")), '')))) as POLICY_TYPE,
               to_varchar((nullif(trim(to_varchar(b."POLICY_EXPIRY_TIME")), ''))) as RISK_END_TIME,
               to_varchar((nullif(trim(to_varchar(b."POLICY_EXPIRY_DATE")), ''))) as RISK_EXPIRY_DATE,
               to_varchar((nullif(trim(to_varchar(b."POLICY_INCEPTION_DATE")), ''))) as RISK_INCEPTION_DATE,
               to_varchar((nullif(trim(to_varchar(b."POLICY_INCEPTION_TIME")), ''))) as RISK_START_TIME
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW b
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk0
                    on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY wk1
                    on wk1."KEY_HASH" = b."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY wk2
                    on wk2."KEY_HASH" = wk1."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS wk3
                    on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk4
                    on wk4."KEY_HASH" = wk3."PARENT_KEY_HASH"
      )
     where hkey in (select hkey from s4) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n4 as (  -- satellite history per sampled key
    select POLICY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and POLICY_HKEY in (select hkey from s4)
     group by 1, 2
),
x4 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_CHANNEL_TYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_REFERENCE_NUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_TERM AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_TYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_END_TIME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_EXPIRY_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_INCEPTION_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_START_TIME AS VARCHAR))), ''), '^^')))) as raw_hash
      from e4 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_POLICY_HEADER', 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_INSURED_DETAILS_RISK_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n4 n full outer join x4 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s5 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct POLICY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_POLICY_HEADER' and record_source = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW'
),
e5 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via resolved_mt__uwr_pol_polp_sp_pv
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(wk0."POLICY_NUMBER"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."POLICY_NUMBER"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey,
               (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as ldts,
               to_varchar((nullif(trim(to_varchar(b."COINSURANCE_APPLICABLE")), ''))) as CO_INSURANCE_INDICATOR,
               to_varchar((nullif(trim(to_varchar(b."FIRST_TIME_EXECUTED")), ''))) as FIRST_YEAR_INDICATOR,
               to_varchar((nullif(trim(to_varchar(b."POLICY_HOLDER")), ''))) as POLICYHOLDER_REFERENCE,
               to_varchar((nullif(trim(to_varchar(b."BAGIC_CONTRACT_ID")), ''))) as POLICY_REFERENCE_NUMBER,
               to_varchar((nullif(trim(to_varchar(b."REMARKS")), ''))) as POLICY_REMARKS,
               to_varchar((nullif(trim(to_varchar(b."POLICY_SUB_STATUS")), ''))) as POLICY_SUB_STATUS,
               to_varchar((nullif(trim(to_varchar(b."POLICY_DURATION")), ''))) as POLICY_TERM,
               to_varchar(coalesce((nullif(trim(to_varchar(b."MASTER_POLICY_TYPE")), '')), (nullif(trim(to_varchar(b."POLICY_TYPE")), '')))) as POLICY_TYPE,
               to_varchar((nullif(trim(to_varchar(b."PAYMENT_FREQUENCY")), ''))) as PREMIUM_FREQUENCY,
               to_varchar((nullif(trim(to_varchar(b."BILL_TO")), ''))) as PREMIUM_PAYER_REFERENCE,
               to_varchar((nullif(trim(to_varchar(b."POLICY_EXPIRY_TIME")), ''))) as RISK_END_TIME,
               to_varchar(coalesce((nullif(trim(to_varchar(b."EXPIRING_POLICY_EXPIRY_DATE")), '')), (nullif(trim(to_varchar(b."POLICY_EXPIRY_DATE")), '')))) as RISK_EXPIRY_DATE,
               to_varchar((nullif(trim(to_varchar(b."POLICY_INCEPTION_DATE")), ''))) as RISK_INCEPTION_DATE,
               to_varchar((nullif(trim(to_varchar(b."POLICY_INCEPTION_TIME")), ''))) as RISK_START_TIME
          from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW b
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk0
                    on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY wk1
                    on wk1."KEY_HASH" = b."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY wk2
                    on wk2."KEY_HASH" = wk1."PARENT_KEY_HASH"
               left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk3
                    on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
      )
     where hkey in (select hkey from s5) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n5 as (  -- satellite history per sampled key
    select POLICY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_POLICY_HEADER
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and POLICY_HKEY in (select hkey from s5)
     group by 1, 2
),
x5 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.CO_INSURANCE_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.FIRST_YEAR_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICYHOLDER_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_REFERENCE_NUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_REMARKS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_SUB_STATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_TERM AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POLICY_TYPE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PREMIUM_FREQUENCY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PREMIUM_PAYER_REFERENCE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_END_TIME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_EXPIRY_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_INCEPTION_DATE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.RISK_START_TIME AS VARCHAR))), ''), '^^')))) as raw_hash
      from e5 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_POLICY_HEADER', 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n5 n full outer join x5 x on x.hkey = n.hkey and x.cdk = n.cdk;

