       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when nullif(trim(wk0."POLICYNO"),'') is not null then nullif(trim(wk0."POLICYNO"), '') end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar(wk0."POLICYNO"), '^^') as business_key, (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as inc_job_updated_at,
