update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS
   set "POLICY_STATUS" = coalesce(to_varchar("POLICY_STATUS"), '') || '_T',
