),
n1 as (  -- satellite history per sampled key
    select POLICY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_AUG_POLICY_TRAVEL_TERMS
     where RECORD_SOURCE = 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' and POLICY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.BAGGAGE_TRACKING_SERVICE_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.COVER_HOURS_COUNT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CRUISE_DAYS_COUNT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CRUISE_SEGMENT_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MAXIMUM_TRIP_ALTITUDE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MODE_OF_TRANSPORT AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MULTIPLE_DESTINATION_CITY_INDICATOR AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TRIP_DESTINATION_COUNTRY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.TRIP_DESTINATION_DETAILS AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'MAXIMUS', 'SAT_AUG_POLICY_TRAVEL_TERMS', 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

-- STEP 3 (pick a key) -- map a sampled BEFORE hkey to its RAW business key. Copy one business_key value to use in STEP 4.
with s_bk as (  -- sampled BEFORE hkeys for this satellite
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_AUG_POLICY_TRAVEL_TERMS'
)
-- via resolved_mt__uwr_pol_polp_sp_pv (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW)  [RAW key columns: FOREIGN_KEY; parent columns: w0_policy_number]
select 'SAT_AUG_POLICY_TRAVEL_TERMS' as satellite, 'MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as record_source,
       MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(wk0."POLICY_NUMBER"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."POLICY_NUMBER"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) as hkey, coalesce(to_varchar(b."FOREIGN_KEY"), '^^') || '|' || coalesce(to_varchar(wk0."POLICY_NUMBER"), '^^') as business_key, (nullif(trim(to_varchar(b."REC_REFRESH_AT")), '')) as inc_job_updated_at,
       'BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW' as raw_table
  from BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW b
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk0
            on wk0."FOREIGN_KEY" = b."FOREIGN_KEY"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY wk1
            on wk1."KEY_HASH" = b."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY wk2
            on wk2."KEY_HASH" = wk1."PARENT_KEY_HASH"
       left join BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS wk3
            on wk3."KEY_HASH" = wk2."PARENT_KEY_HASH"
 where MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_POLICY|' || (nullif(trim(case when coalesce(nullif(trim(wk0."POLICY_NUMBER"),''), nullif(trim(b."FOREIGN_KEY"),'')) is not null then coalesce(nullif(trim(wk0."POLICY_NUMBER"), ''), nullif(trim(b."FOREIGN_KEY"), '')) end),'')) AS VARCHAR))), '')) in (select hkey from s_bk)
limit 20;

-- STEP 4 (force the change) -- fill <BK> from STEP 3, run this UPDATE in UTILS. STEP 5: dbt run --select this sat. STEP 6: set phase='AFTER' and re-run STEP 2.
-- MAXIMUS_TRAVEL_NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW (BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW): change ONE sampled key (fill <..> from the b-map result)
update BAGIC_PROD_MIRROR_DB.MAXI_RAW.NONHLTH_TRV_UWR_VW_DATA_POLICY_DETAILS_POLICY_PROPERTY_SIMPLE_PROPERTY_PIVOT_VW
   set "BAGGAGE_TRACKING_SERVICE_APPLICABLE" = coalesce(to_varchar("BAGGAGE_TRACKING_SERVICE_APPLICABLE"), '') || '_T',
       "REC_REFRESH_AT" = current_timestamp()
 where "FOREIGN_KEY" = '<FOREIGN_KEY>';

-- STEP 7 (result for THIS sat) -- after AFTER capture, run this. PASS = every changed key got >= 1 new row; NOT TESTED = no change reached the sample.
with b as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'BEFORE' and satellite = 'SAT_AUG_POLICY_TRAVEL_TERMS'
),
a as (
    select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT
     where run_id = $DM_H_RUN and phase = 'AFTER'  and satellite = 'SAT_AUG_POLICY_TRAVEL_TERMS'
),
k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'MAXIMUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1)  as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)',
           iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), record_source;



----------------------------------------------------------------------------------------
-- 12. MAXIMUS — STEP 7 -- CDC result (all satellites)   [Implemented]
-- Joins the BEFORE and AFTER captures of the same run id. raw_changed compares the
-- normalised RAW payload hash (same UPPER/TRIM/NULL rules as the HASHDIFF, so a
-- case-only RAW edit is not a change); new_rows = satellite rows added for the key
-- between the captures.
----------------------------------------------------------------------------------------
with b as (select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT where run_id = $DM_H_RUN and phase = 'BEFORE' and project = 'MAXIMUS'),
     a as (select * from BAGIC_PREPROD_CURATED_DB.UTILS.DM_H_CDC_SNAPSHOT where run_id = $DM_H_RUN and phase = 'AFTER'  and project = 'MAXIMUS'),
     k as (
    select b.satellite, b.record_source, b.hkey, b.cdk,
           not equal_null(b.raw_hash, a.raw_hash) as raw_changed,
           a.sat_rows - b.sat_rows as new_rows
      from b join a
        on a.satellite = b.satellite and a.record_source = b.record_source
       and a.hkey = b.hkey and equal_null(a.cdk, b.cdk)
)
select 'MAXIMUS' as project, satellite, record_source,
       count(*) as changed_keys,
       count_if(new_rows >= 1) as changed_with_new_row,
       count_if(new_rows < 1) as changed_without_new_row,
       iff(changed_keys = 0, 'NOT TESTED (no source change in sample)', iff(changed_without_new_row = 0, 'PASS', 'FAIL')) as status
  from k
 where raw_changed
 group by satellite, record_source
 order by iff(status = 'FAIL', 0, 1), satellite, record_source;
